<section class="py-20 bg-slate-900 text-white" x-data="{ charges: 250000, collection: 92, denial: 12, target: 97, get annual(){ return Math.max(0, this.charges * 12 * ((this.target-this.collection)/100)) }, get denied(){ return this.charges * 12 * (this.denial/100) } }"><div class="max-w-6xl mx-auto px-6"><div class="text-center max-w-3xl mx-auto"><h2 class="text-4xl font-bold">{{ $title ?? 'Estimate your revenue opportunity' }}</h2><p class="mt-4 text-slate-300">{{ $description ?? 'Use your approximate figures to identify potential revenue leakage. Results are estimates, not guarantees.' }}</p></div><div class="mt-12 grid lg:grid-cols-2 gap-8"><div class="bg-white/10 border border-white/10 rounded-2xl p-7 space-y-6"><label class="block">Monthly charges ($)<input x-model.number="charges" type="number" min="0" class="mt-2 w-full rounded-lg text-slate-900"></label><label class="block">Current net collection rate (%)<input x-model.number="collection" type="number" min="0" max="100" step="0.1" class="mt-2 w-full rounded-lg text-slate-900"></label><label class="block">Current denial rate (%)<input x-model.number="denial" type="number" min="0" max="100" step="0.1" class="mt-2 w-full rounded-lg text-slate-900"></label></div><div class="rounded-2xl bg-blue-600 p-8 flex flex-col justify-center"><p class="text-blue-100">Estimated annual collection opportunity</p><strong class="mt-2 text-5xl" x-text="annual.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0})"></strong><p class="mt-7 text-blue-100">Annual value of initially denied claims</p><strong class="mt-2 text-3xl" x-text="denied.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0})"></strong><a href="#rcm-assessment" class="mt-8 rounded-lg bg-white text-blue-700 text-center font-bold px-6 py-3">{{ $cta_text ?? 'Request a Detailed Assessment' }}</a></div></div><p class="mt-5 text-xs text-slate-400 text-center">Illustrative estimate only. Actual results depend on payer mix, contracts, workflows, and other factors.</p></div></section>
